package agentdesk

const page = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Chief · Workspace</title><style>
:root{font:15px/1.5 system-ui,sans-serif;color:#23352e;background:#f5f5ef}*{box-sizing:border-box}body{margin:0}button,input,select,textarea{font:inherit}button{cursor:pointer;background:#285743;color:white;border:0;border-radius:8px;padding:9px 14px}button:disabled{opacity:.5}header{min-height:76px;padding:15px 24px;display:flex;align-items:center;gap:24px;border-bottom:1px solid #d8dfd5;background:#fcfcf8}h1{font-size:19px;margin:0;white-space:nowrap}.brand small{display:block;color:#64746b;font-size:11px;letter-spacing:1.5px;text-transform:uppercase}#searchform{display:flex;gap:8px;width:min(700px,65%)}input,select,textarea{border:1px solid #cbd6cc;border-radius:8px;padding:9px;background:white;color:inherit}input{min-width:0;flex:1}#scope{flex:0 1 140px}#metadata{font-size:11px}.layout{display:grid;grid-template-columns:minmax(360px,1fr) minmax(350px,420px);height:calc(100vh - 76px)}main{padding:24px;overflow:auto}.eyebrow{font-size:11px;letter-spacing:1.5px;text-transform:uppercase;color:#64746b}h2{font-size:26px;font-weight:550;margin:5px 0 18px}.card{background:#fff;border:1px solid #d8dfd5;border-radius:12px;padding:18px;margin-bottom:16px}.muted{font-size:13px;color:#6a796f}.commitment{display:flex;gap:12px;align-items:center;padding:10px 0;border-top:1px solid #edf0eb}.commitment:first-child{border:0}.commitment span{flex:1}.commitment button{background:#edf4ee;color:#285743;padding:5px 10px}iframe{border:1px solid #d8dfd5;border-radius:12px;background:#fff;width:100%;height:60vh}aside{display:flex;flex-direction:column;min-height:0;background:#fcfcf8;border-left:1px solid #d8dfd5}.chathead{padding:20px;border-bottom:1px solid #e2e7dd}.chathead strong{font-size:18px}.chathead p{margin:4px 0 0}#messages{flex:1;overflow:auto;padding:20px}.message{white-space:pre-wrap;overflow-wrap:anywhere;padding:13px 15px;background:#edf2eb;border-radius:10px;margin-bottom:16px}.message.user{background:#fff;border:1px solid #dce3d9;margin-left:22px}.message small{display:block;color:#708075;font-size:10px;margin-bottom:5px}#chatform{padding:16px;border-top:1px solid #e2e7dd}textarea{width:100%;resize:vertical;min-height:80px}#chatform .actions{display:flex;align-items:center;justify-content:space-between;margin-top:8px}.quiet{background:transparent;color:#285743;padding:4px}#notice{color:#9e3e24;white-space:pre-wrap}pre{white-space:pre-wrap;overflow-wrap:anywhere}.hidden{display:none}@media(max-width:760px){header{height:auto;flex-wrap:wrap;padding:12px}#searchform{width:100%}.layout{display:block;height:auto}main{padding:16px}aside{height:70vh;border-top:1px solid #d8dfd5}iframe{height:45vh}}
</style></head><body><header><div class="brand"><small>Iugum workspace</small><h1 id="name">Chief</h1><div id="metadata" class="muted"></div></div><form id="searchform"><input id="query" aria-label="Search" placeholder="Find that thing we worked on…" required><input id="scope" aria-label="Search scope or project" list="scopes" value="all" placeholder="Scope or project"><datalist id="scopes"><option value="all"><option value="transcripts"><option value="wiki"><option value="memory"><option value="tasks"><option value="claude"><option value="codex"><option value="cursor"><option value="opencode"><option value="ffai"></datalist><button>Search</button></form></header><div class="layout"><main><h2>Current work</h2><p id="notice" role="alert"></p><section id="approvals" class="card hidden"><strong>Needs your decision</strong><div id="approvalitems"></div></section><section class="card"><strong>Commitments</strong><div id="commitments"></div><p class="muted" id="checked"></p></section><section id="results" class="card hidden"><strong>Search results</strong><div id="hits"></div></section><div id="wikiintro" class="muted">Your wiki appears here when a wiki URL is configured. This workspace keeps your conversation beside it.</div><iframe id="wiki" class="hidden" title="Wiki" referrerpolicy="no-referrer"></iframe></main><aside><div class="chathead"><strong>One conversation</strong><p class="muted" id="connection">Your history stays here.</p></div><div id="messages" aria-live="polite"></div><form id="chatform"><textarea id="text" aria-label="Message Chief" placeholder="What's on your mind?" required></textarea><div class="actions"><button class="quiet" type="button" id="status">Status</button><button id="send">Send</button></div><p class="muted">Track: /commit title · Due: /due c1 YYYY-MM-DD · Finish: /done c1</p></form></aside></div><script>
const $=id=>document.getElementById(id);async function api(path,options){const r=await fetch(path,options);const data=await r.json();if(!r.ok)throw Error(data.error||'Request failed');return data}function notice(e){$('notice').textContent=e.message||String(e)}function message(m){const el=document.createElement('div');el.className='message '+(m.role==='user'?'user':'assistant');const meta=document.createElement('small');meta.textContent=(m.role==='user'?'You':'Assistant')+' · '+new Date(m.at).toLocaleString();el.append(meta,document.createTextNode(m.text));$('messages').append(el)}async function refresh(){const [s,m,approvals]=await Promise.all([api('/api/status'),api('/api/messages'),api('/api/approvals')]);renderApprovals(approvals);$('name').textContent=s.name;document.title=s.name+' · Workspace';$('metadata').textContent=Object.entries(s.metadata||{}).map(([k,v])=>k+': '+v).join(' · ');$('connection').textContent=s.chat_available?'Your history stays here.':'Local commands available · conversational chat not configured';$('checked').textContent='Local records · '+new Date(s.now).toLocaleString();$('messages').replaceChildren();(m||[]).forEach(message);$('messages').scrollTop=$('messages').scrollHeight;$('commitments').replaceChildren();const active=(s.commitments||[]).filter(c=>!c.done);if(!active.length){const p=document.createElement('p');p.className='muted';p.textContent='Nothing promised yet. Use /commit in chat to track something.';$('commitments').append(p)}active.forEach(c=>{const row=document.createElement('div');row.className='commitment';const span=document.createElement('span');span.textContent=c.title+(c.due?' · due '+c.due:'')+(c.deferred?' · saved for later':'');const button=document.createElement('button');button.textContent='Done';button.onclick=()=>send('/done '+c.id);const focus=document.createElement('button');focus.textContent='Focus';focus.onclick=()=>send('/focus '+c.id);row.append(span,focus,button);$('commitments').append(row)});if(s.wiki_url&&$('wiki').getAttribute('src')!==s.wiki_url){$('wiki').src=s.wiki_url;$('wiki').classList.remove('hidden');$('wikiintro').classList.add('hidden')}}let busy=false;async function send(text){if(busy)return;busy=true;$('send').disabled=true;$('notice').textContent='';try{await api('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text})});$('text').value='';await refresh()}catch(e){notice(e)}finally{busy=false;$('send').disabled=false}}$('chatform').onsubmit=e=>{e.preventDefault();send($('text').value)};$('status').onclick=()=>send('status');$('text').onkeydown=e=>{if(e.key==='Enter'&&(e.metaKey||e.ctrlKey)){$('chatform').requestSubmit()}};$('searchform').onsubmit=async e=>{e.preventDefault();$('notice').textContent='';try{const data=await api('/api/search?q='+encodeURIComponent($('query').value)+'&scope='+encodeURIComponent($('scope').value));$('results').classList.remove('hidden');$('hits').replaceChildren();renderResults(data)}catch(err){notice(err)}};function renderApprovals(items){const root=$('approvalitems');root.replaceChildren();$('approvals').classList.toggle('hidden',!items.length);for(const a of items){const box=document.createElement('div');box.style.cssText='padding:12px 0;border-top:1px solid #e2e7dd';const title=document.createElement('strong');title.textContent=a.title;const meta=document.createElement('p');meta.className='muted';meta.textContent=a.id+' · '+a.status+' · '+new Date(a.created).toLocaleString();box.append(title,meta);const d=document.createElement('details');const summary=document.createElement('summary');summary.textContent='Review action and evidence';const p=document.createElement('pre');p.textContent='Action: '+a.action+'\n'+JSON.stringify(a.payload||{},null,2)+'\n\n'+(a.evidence||[]).map(e=>[e.label,e.path,e.text,'Digest: '+(e.digest||'')].filter(Boolean).join('\n')).join('\n\n');d.append(summary,p);box.append(d);if(a.result){const result=document.createElement('p');result.textContent=a.result;box.append(result)}if(a.status==='executing'){const p=document.createElement('p');p.textContent='Execution started. If interrupted, inspect the result before requesting another attempt.';box.append(p)}if(a.status==='pending'){for(const decision of ['approve','reject']){const b=document.createElement('button');b.type='button';b.textContent=decision==='approve'?'Approve once':'Reject';b.style.margin='10px 8px 0 0';b.onclick=async()=>{b.disabled=true;try{await api('/api/approvals/'+encodeURIComponent(a.id),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({decision,digest:a.digest})});await refresh()}catch(e){notice(e);b.disabled=false}};box.append(b)}}root.append(box)}}
function renderResults(data){
 const hit=$('hits'),cards=[];const field=(x,k)=>x[k]??x[k.toLowerCase()]??'';
 const add=(title,source,text,provenance)=>{const card=document.createElement('article');card.style.cssText='padding:14px 0;border-top:1px solid #e2e7dd';const heading=document.createElement('strong');heading.textContent=title||'Untitled source';const meta=document.createElement('div');meta.className='muted';meta.textContent=source;const p=document.createElement('p');p.style.whiteSpace='pre-wrap';p.textContent=String(text).slice(0,200)+(String(text).length>200?'…':'');card.append(heading,meta,p);const details=document.createElement('details');const summary=document.createElement('summary');summary.textContent='Source and full passage';const pre=document.createElement('pre');pre.textContent=provenance+'\n\n'+text;details.append(summary,pre);card.append(details);cards.push(card)};
 if(data&&typeof data==='object'){
  const freshness=document.createElement('p');freshness.className='muted';const stamp=new Date(data.indexed_at);freshness.textContent=data.indexed_at&&!isNaN(stamp)&&stamp.getFullYear()>1?'Index updated '+stamp.toLocaleString():'Index freshness not yet available';if(data.partial)freshness.textContent+=' · Partial index';hit.append(freshness);
  if(data.warnings&&data.warnings.length){const d=document.createElement('details');const summary=document.createElement('summary');summary.textContent='Source notices ('+data.warnings.length+')';const p=document.createElement('p');p.className='muted';p.style.whiteSpace='pre-wrap';p.textContent=Array.isArray(data.warnings)?data.warnings.join('\n'):String(data.warnings);d.append(summary,p);hit.append(d)}
  for(const t of data.transcripts||[]){const project=String(field(t,'Project')).split('/').filter(Boolean).pop();add(project||field(t,'Session')||'Transcript',[field(t,'Platform'),field(t,'Account'),field(t,'Timestamp')].filter(Boolean).join(' · '),field(t,'Text'),field(t,'Path')+':'+field(t,'Line')+'\nSession: '+field(t,'Session'))}
  for(const w of data.wiki||[])add(String(w.path).split('/').pop(),'Wiki',w.text,w.path);
  for(const m of data.memory||[])add(field(m,'Key'),'Memory · '+field(m,'NS')+' · '+field(m,'Type'),field(m,'Value'),field(m,'NS')+'/'+field(m,'Key'));
  for(const task of data.tasks||[])add(task.title||task.id,[task.id,task.status,task.priority===undefined?'':'Priority '+task.priority,task.checked_at?'Checked '+new Date(task.checked_at).toLocaleString():''].filter(Boolean).join(' · '),task.description||'', 'Repository: '+task.repo+'\nDependencies: '+(typeof task.dependencies==='string'?task.dependencies:JSON.stringify(task.dependencies||[])));
  if(data.task_sources&&Object.keys(data.task_sources).length){const details=document.createElement('details');const summary=document.createElement('summary');summary.textContent='Task source freshness';const pre=document.createElement('pre');pre.textContent=typeof data.task_sources==='string'?data.task_sources:JSON.stringify(data.task_sources,null,2);details.append(summary,pre);hit.append(details);}
 }
 if(!cards.length){const p=document.createElement('p');p.className='muted';p.textContent=typeof data==='string'?data:'No matching passages.';hit.append(p);return}
 let shown=0;const more=document.createElement('button');more.className='quiet';more.type='button';const next=()=>{cards.slice(shown,shown+5).forEach(card=>hit.insertBefore(card,more));shown=Math.min(shown+5,cards.length);more.textContent='Show more ('+(cards.length-shown)+' remaining)';more.hidden=shown>=cards.length};more.onclick=next;hit.append(more);next();
}refresh().catch(notice);
</script></body></html>`
